const items = $input.all();
if (items.length !== 1) throw new Error('One support request required');
const p = items[0].json.body;
const keys = ['schemaVersion','ticketId','projectId','revision','replyTo','recipient','subject','message','attachments'];
if (!p || Object.keys(p).sort().join() !== keys.sort().join() || p.schemaVersion !== 1) throw new Error('Invalid support schema');
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const email = /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)+$/;
if (typeof p.ticketId !== 'string' || typeof p.projectId !== 'string' || !uuid.test(p.ticketId) || !uuid.test(p.projectId) || !Number.isInteger(p.revision) || p.revision < 1) throw new Error('Invalid support identity');
for (const address of [p.replyTo,p.recipient]) if (typeof address !== 'string' || address.length > 254 || !email.test(address) || address.endsWith('.invalid')) throw new Error('Invalid email');
if (p.subject !== '[Atelier support] ' + p.ticketId || typeof p.message !== 'string' || p.message.length < 10 || p.message.length > 15000) throw new Error('Invalid support message');
if (!Array.isArray(p.attachments) || p.attachments.length < 1 || p.attachments.length > 2) throw new Error('Invalid attachments');
const binary = {};
for (let i = 0; i < p.attachments.length; i++) {
  const a = p.attachments[i];
  const name = i === 0 ? 'conversation.txt' : 'maquette.html';
  const mime = i === 0 ? 'text/plain' : 'text/html';
  if (!a || Object.keys(a).sort().join() !== 'data,mime,name' || a.name !== name || a.mime !== mime || typeof a.data !== 'string' || a.data.length > 6000000 || !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(a.data) || a.data.length === 0) throw new Error('Invalid attachment');
  binary['file' + i] = { data: a.data, mimeType: a.mime, fileName: a.name };
}
return [{json: {ticketId:p.ticketId,recipient:p.recipient,replyTo:p.replyTo,subject:p.subject,message:p.message},binary}];

const result = $input.first().json;
if (typeof result.id !== 'string' || !/^[A-Za-z0-9_-]{1,200}$/.test(result.id) || !Array.isArray(result.labelIds) || !result.labelIds.includes('SENT')) throw new Error('Mail send not confirmed');
return [{json:{schemaVersion:1,ticketId:$('Preparer le dossier support').first().json.ticketId,status:'sent',messageId:result.id}}];
